using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed Cosmos DB indexing support
            // (HasIndex is no longer valid for Cosmos — manage indexes in Azure Portal).

            // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
            // Preserve the old property name so existing documents are still found.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
            // Preserve the old composite format so existing documents are matched.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();
        });
    }
}

// Generates ids in the legacy "Discriminator|Key" format used by EF Core <= 8.
class LegacyIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

